const { withAppBuildGradle } = require("expo/config-plugins");

// Korean fork: every published Android APK is signed with the public React
// Native debug key (SHA-256 FA:C6:17:45:…:91:03:3B:9C). Android only installs an
// update over an existing app when the signer matches, so release builds must
// keep using exactly that key. android/ is regenerated by `expo prebuild`, and
// its app/debug.keystore can change with the template, so release signing reads
// the committed copy in apps/mobile/signing instead.
const MARKER = "// @generated withAndroidKoreanReleaseSigning";
const SIGNING_CONFIG = `
        koreanRelease {
            ${MARKER}
            storeFile file('../../signing/t3code-ko-debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }`;

module.exports = function withAndroidKoreanReleaseSigning(config) {
  return withAppBuildGradle(config, (nextConfig) => {
    let contents = nextConfig.modResults.contents;
    if (contents.includes(MARKER)) return nextConfig;

    const signingConfigs = /signingConfigs\s*\{/;
    const releaseSigning = /(release\s*\{[^}]*?signingConfig\s+)signingConfigs\.debug/;
    if (!signingConfigs.test(contents) || !releaseSigning.test(contents)) {
      throw new Error(
        "withAndroidKoreanReleaseSigning: app/build.gradle no longer matches the expected template.",
      );
    }
    contents = contents.replace(signingConfigs, (match) => `${match}${SIGNING_CONFIG}`);
    contents = contents.replace(releaseSigning, "$1signingConfigs.koreanRelease");
    nextConfig.modResults.contents = contents;
    return nextConfig;
  });
};
